import {state,subscribe,RELAYS,LABELS,icons,relayControlLocked,commandStatus} from './state.js';
import {connect,publish,saveToken} from './mqtt.js';
const view=document.querySelector('#view');const dialog=document.querySelector('#confirmDialog');let route=location.hash.slice(1)||'dashboard';let selectedRelay='pump';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const val=(x,u='')=>x==null?'<span class="mono">รอข้อมูล</span>':`${esc(x)}${u}`;
function connection(){const c=document.querySelector('#connection');const label=state.emergency?.active?'Emergency Stop':state.connected?'Online':'รอข้อมูลจากอุปกรณ์';c.className=`connection ${state.emergency?.active?'emergency':state.connected?'online':'offline'}`;c.lastElementChild.textContent=label;const n=state.aiAlerts.length+(state.emergency?.active?1:0);const badge=document.querySelector('#alertBadge');badge.hidden=!n;badge.textContent=n}
function card(r){const v=state.relays[r],t=state.timers[r],lock=relayControlLocked();return `<article class="card device-card"><div class="device-icon">${icons[r]}</div><h3>${LABELS[r]}</h3><p class="device-state ${v==='ON'?'active':''}">${v==null?'รอข้อมูลจาก ESP8266':v==='ON'?'เปิด':'ปิด'}</p>${t?.active?`<p class="mono">กำลังทำงาน · ${t.unlimited?'ไม่จำกัด':`${Math.ceil(t.remaining||0)} วินาที`}</p>`:''}${commandStatus(r)?`<p class="mono">${commandStatus(r)}</p>`:''}<div class="device-actions"><button class="btn ${v==='ON'?'secondary':'primary'} small relay-btn" data-relay="${r}" data-value="${v==='ON'?'OFF':'ON'}" ${lock?'disabled':''}>${v==='ON'?'ปิด':'เปิด'}</button><button class="btn secondary small timer-btn" data-relay="${r}" ${lock?'disabled':''}>ตั้งเวลา</button></div></article>`}
function alerts(){const rows=state.aiAlerts.map(a=>`<div class="list-card"><span>AI Alert · ${esc(a.status||'status')}</span><span class="mono">${esc(a.id||'ไม่มี id')}</span></div>`).join('');return rows||'<div class="empty">ยังไม่มี Alert จาก ESP8266</div>'}
function dashboard(){const d=state.device,s=state.sensor;return `<section class="section-head"><div><h2>ภาพรวมสวน</h2><p>สถานะจากอุปกรณ์จริงเท่านั้น</p></div><span class="mono">${d?.time?esc(d.time.slice(11,19)):'--:--:--'}</span></section>${state.emergency?.active?`<div class="card emergency"><h3>🛑 ระบบหยุดฉุกเฉิน</h3><p>อุปกรณ์ทั้งหมดถูกปิดเพื่อความปลอดภัย และปุ่มเปิด Relay ถูกล็อก</p><button class="btn danger reset-btn">รีเซ็ต Emergency</button></div>`:''}<div class="grid sensor-grid"><article class="card sensor-card"><span class="metric-icon">🌡️</span><p class="card-label">อุณหภูมิอากาศ · DHT11</p><div class="metric">${val(s?.temperature,'°C')}</div></article><article class="card sensor-card"><span class="metric-icon">💧</span><p class="card-label">ความชื้นอากาศ · DHT11</p><div class="metric">${val(s?.humidity,'%')}</div></article></div><div class="card farm-card"><div><strong>🌱 แปลงแตงกวา</strong><p>Reminder จาก Firmware</p><strong>${state.reminder?.due?esc(state.reminder.due):'รอข้อมูล Reminder จากอุปกรณ์'}</strong></div><span class="mono">${state.reminder?.event?esc(state.reminder.event):'--'}</span></div><div class="section-head"><h2>สถานะอุปกรณ์</h2><p>4 Relay</p></div><div class="grid device-grid">${RELAYS.map(card).join('')}</div><div class="section-head"><h2>การแจ้งเตือน</h2><p>${state.aiAlerts.length+(state.emergency?.active?1:0)} รายการจากอุปกรณ์</p></div><div class="card">${alerts()}</div><div class="card quick-card"><div><h3>⏱ ตั้งเวลา</h3><p>จัดการการทำงานอัตโนมัติ</p></div><a class="btn secondary" href="#schedule">ดูตาราง →</a></div><div class="card emergency"><h3>🛑 หยุดทั้งหมด</h3><p>ส่งคำสั่ง Emergency Stop และรอการยืนยันจาก ESP8266</p><button class="btn danger emergency-btn" ${relayControlLocked()?'disabled':''}>หยุดทุก Relay</button></div>`}
function devices(){const r=selectedRelay,t=state.timers[r],sch=state.schedules[r];return `<div class="section-head"><div><h2>อุปกรณ์</h2><p>${state.connected?'ESP8266 Online':'รอข้อมูลจาก ESP8266'}</p></div></div><div class="grid device-grid">${RELAYS.map(card).join('')}</div><div class="section-head"><h2>รายละเอียดอุปกรณ์</h2></div><div class="tabs">${RELAYS.map(x=>`<button class="tab ${selectedRelay===x?'active':''}" data-select="${x}">${icons[x]} ${LABELS[x]}</button>`).join('')}</div><div class="card stack"><div class="row"><div><h3>${icons[r]} ${LABELS[r]}</h3><p class="device-state">สถานะจริง: ${val(state.relays[r])}</p></div><span class="mono">${commandStatus(r)||'พร้อมดูข้อมูล'}</span></div><div class="list-card"><span>Manual</span><button class="btn secondary small relay-btn" data-relay="${r}" data-value="${state.relays[r]==='ON'?'OFF':'ON'}" ${relayControlLocked()?'disabled':''}>${state.relays[r]==='ON'?'ปิด':'เปิด'}</button></div><div class="list-card"><span>Timer</span><span class="mono">${t?.active?(t.unlimited?'ไม่จำกัด':`${t.remaining||0} วินาที`):'ไม่ได้ทำงาน'}</span></div><div class="list-card"><span>Schedule</span><span class="mono">${sch?.slots?.length||0} slots จาก ESP</span></div><div class="list-card"><span>Auto</span><span class="mono">${sch?'ข้อมูลจาก Firmware':'รอข้อมูล'}</span></div><div class="notice">History จะแสดงเฉพาะ Event Log ที่ Firmware ส่งผ่าน MQTT; ขณะนี้ยังไม่มี topic Event Log ใน contract</div></div>`}
function schedule(){const r=selectedRelay,slots=state.schedules[r]?.slots||[];return `<div class="section-head"><div><h2>ตั้งเวลา</h2><p>สูงสุด 4 ช่วงต่อ Relay · Firmware ตรวจ overlap ซ้ำ</p></div></div><div class="tabs">${RELAYS.map(x=>`<button class="tab ${r===x?'active':''}" data-select="${x}">${icons[x]} ${LABELS[x]}</button>`).join('')}</div><div class="stack">${[0,1,2,3].map(i=>{const s=slots[i]||{};return `<div class="card schedule-slot"><div class="field"><label>เปิด</label><input type="time" value="${esc(s.on||'')}" data-on="${i}"></div><div class="field"><label>ปิด</label><input type="time" value="${esc(s.off||'')}" data-off="${i}"></div><div class="switch-wrap"><label class="field"><span>ใช้งาน</span><button class="switch ${s.enabled?'on':''}" data-slot="${i}" aria-label="เปิดใช้งานช่วงเวลา ${i+1}"><i></i></button></label></div><button class="btn secondary small save-schedule" data-relay="${r}">บันทึกตาราง</button></div>`}).join('')}</div><button class="btn danger full delete-schedule">ลบตารางของ ${LABELS[r]}</button>`}
function settings(){return `<div class="section-head"><div><h2>ตั้งค่า</h2><p>การเชื่อมต่อและความปลอดภัย</p></div></div><div class="stack"><div class="card"><h3>🔐 สิทธิ์การควบคุม</h3><p class="device-state">สถานะ: ${state.auth.authenticated?state.auth.role:'Viewer'}</p><div class="field"><label>Dashboard token (เก็บเฉพาะ session นี้)</label><input id="tokenInput" type="password" placeholder="วาง token ที่นี่"></div><button class="btn secondary full token-save">บันทึก token</button></div><div class="card"><h3>📡 Connection</h3><div class="list-card"><span>Wi-Fi</span><b>${state.device?.wifi||'รอข้อมูล'}</b></div><div class="list-card"><span>MQTT</span><b>${state.connected?'Connected':'Disconnected'}</b></div><div class="list-card"><span>Device ID</span><b>${esc(state.device?.device||'รอข้อมูล')}</b></div></div><div class="card"><h3>🕐 Time</h3><div class="list-card"><span>DS3231 RTC</span><b>${state.device?.rtc?'Synced':'รอข้อมูล'}</b></div><div class="list-card"><span>NTP</span><b>${state.device?.clockValid?'Synced':'รอข้อมูล'}</b></div></div><div class="card"><h3>🔔 Telegram</h3><div class="list-card"><span>สถานะ</span><b>${state.telegram?.configured?'Connected':'รอข้อมูล'}</b></div><button class="btn secondary full telegram-test" ${relayControlLocked()?'disabled':''}>ทดสอบ Telegram</button></div><div class="card"><h3>🔐 OTA Update</h3><div class="list-card"><span>Firmware</span><b>${esc(state.device?.firmware||'รอข้อมูล')}</b></div><div class="notice warning">Firmware ปัจจุบันไม่มี MQTT topic หรือ heartbeat field สำหรับ OTA status จึงไม่สามารถยืนยัน OTA จาก ESP8266 ได้; ต้องเพิ่ม contract ก่อนจึงจะทำ interlock จากอุปกรณ์ได้</div><button class="btn secondary full ota-check">ตรวจสอบ Firmware</button></div><div class="card emergency"><h3>🛑 Emergency Stop</h3><p>สถานะ: ${state.emergency?.active?'Emergency Stop':'Normal'}</p><button class="btn danger emergency-btn" ${relayControlLocked()?'disabled':''}>หยุดทุก Relay</button></div><div class="card"><h3>💾 Backup / Restore</h3><div class="device-actions"><button class="btn secondary backup-btn">Backup</button><button class="btn secondary restore-btn">Restore</button><button class="btn danger reset-settings">Reset Settings</button></div></div><div class="card"><h3>ℹ️ About</h3><p class="device-state">สวนลุงนะ Smart Farm · MQTT contract จาก SmartFarm_V6_PRODUCTION.ino</p><p class="mono">Soil Moisture: ยังไม่มี topic จาก Firmware</p></div></div>`}
function account(){const permissions=['ดู Dashboard','เปิด/ปิด Relay','ตั้ง Schedule','ตั้ง MQTT','ตั้ง Telegram','Emergency Stop','OTA Firmware','จัดการผู้ใช้งาน'];return `<div class="section-head"><div><h2>บัญชี</h2><p>สิทธิ์และความปลอดภัย</p></div></div><div class="card farm-card"><div><strong>สวนลุงนะ Smart Farm</strong><p>Role จาก bridge: ${esc(state.auth.role)}</p></div><span>${state.auth.authenticated?'● Authenticated':'○ Viewer'}</span></div><div class="section-head"><h2>สิทธิ์ผู้ดูแล</h2></div><div class="card stack">${permissions.map(x=>`<div class="list-card"><span>${x}</span><span class="mono">${state.auth.role==='admin'?'อนุญาต':'ต้องมีสิทธิ์ Admin'}</span></div>`).join('')}</div><div class="notice">สิทธิ์ควบคุมถูกตรวจซ้ำที่ backend ทุกคำสั่ง ไม่อาศัยการซ่อนปุ่มบน browser เพียงอย่างเดียว</div>`}
function render(){connection();view.innerHTML=route==='dashboard'?dashboard():route==='devices'?devices():route==='schedule'?schedule():route==='settings'?settings():account();document.querySelectorAll('[data-route]').forEach(a=>a.classList.toggle('active',a.dataset.route===route));bind()}
function confirm(title,text,fn){document.querySelector('#dialogTitle').textContent=title;document.querySelector('#dialogText').textContent=text;dialog.returnValue='';dialog.showModal();dialog.addEventListener('close',()=>{if(dialog.returnValue==='confirm')fn()},{once:true})}
function bind(){document.querySelectorAll('.relay-btn').forEach(b=>b.onclick=()=>confirm('ยืนยันการสั่งงาน',`ส่งคำสั่ง ${b.dataset.value} ไปยัง ${LABELS[b.dataset.relay]}?`,async()=>{try{await publish(`smartfarm/relay/${b.dataset.relay}/set`,b.dataset.value,b.dataset.relay);render()}catch(e){alert(e.message)}}));document.querySelectorAll('.timer-btn').forEach(b=>b.onclick=async()=>{const p=prompt('วินาที หรือ UNLIMITED / CANCEL','60');if(p)try{await publish(`smartfarm/relay/${b.dataset.relay}/timer/set`,p)}catch(e){alert(e.message)}});document.querySelectorAll('.emergency-btn').forEach(b=>b.onclick=()=>confirm('หยุดระบบฉุกเฉิน','การทำงานของ Relay ทั้งหมดจะหยุดลง',async()=>{try{await publish('smartfarm/emergency/set','STOP')}catch(e){alert(e.message)}}));document.querySelectorAll('.reset-btn').forEach(b=>b.onclick=()=>publish('smartfarm/emergency/set','RESET').catch(e=>alert(e.message)));document.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{selectedRelay=b.dataset.select;render()});document.querySelectorAll('[data-slot]').forEach(b=>b.onclick=()=>b.classList.toggle('on'));document.querySelectorAll('.telegram-test').forEach(b=>b.onclick=()=>publish('smartfarm/config/telegram/test','').catch(e=>alert(e.message)));document.querySelectorAll('.token-save').forEach(b=>b.onclick=()=>{const v=document.querySelector('#tokenInput')?.value;if(v)saveToken(v)});document.querySelectorAll('.backup-btn').forEach(b=>b.onclick=()=>confirm('ยืนยัน Backup','ระบบจะสร้างคำขอ Backup แต่ Firmware ปัจจุบันยังไม่มี MQTT topic สำหรับการดำเนินการนี้',()=>alert('ยังไม่ส่งคำสั่ง: Firmware ไม่มี Backup topic')));document.querySelectorAll('.restore-btn').forEach(b=>b.onclick=()=>confirm('ยืนยัน Restore','Firmware ปัจจุบันยังไม่มี MQTT topic สำหรับ Restore และจะไม่ส่งคำสั่งที่ไม่อยู่ใน contract',()=>alert('ยังไม่ส่งคำสั่ง: Firmware ไม่มี Restore topic')));document.querySelectorAll('.ota-check').forEach(b=>b.onclick=()=>alert('Firmware ปัจจุบันไม่มี MQTT topic สำหรับ OTA status/check'));document.querySelectorAll('.reset-settings').forEach(b=>b.onclick=()=>confirm('รีเซ็ต Settings','การตั้งค่าที่ Firmware บันทึกไว้จะถูกจัดการตามช่องทางที่ปลอดภัย',()=>alert('ต้องดำเนินการผ่าน Firmware/LittleFS โดยตรง')));document.querySelectorAll('.delete-schedule').forEach(b=>b.onclick=()=>confirm('ลบตาราง','ส่ง DELETE ไปยัง Firmware หรือไม่',()=>publish(`smartfarm/schedule/${selectedRelay}/set`,'DELETE').catch(e=>alert(e.message))));document.querySelectorAll('.save-schedule').forEach(b=>b.onclick=()=>{const slots=[0,1,2,3].map(i=>({enabled:document.querySelector(`[data-slot="${i}"]`)?.classList.contains('on'),on:document.querySelector(`[data-on="${i}"]`)?.value||'',off:document.querySelector(`[data-off="${i}"]`)?.value||''})).filter(s=>s.enabled||s.on||s.off);const mins=x=>Number(x.slice(0,2))*60+Number(x.slice(3));const bad=slots.some(s=>!/^([01]\d|2[0-3]):[0-5]\d$/.test(s.on)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(s.off)||mins(s.on)>=mins(s.off));const overlap=slots.some((a,i)=>slots.some((b,j)=>i<j&&mins(a.on)<mins(b.off)&&mins(b.on)<mins(a.off)));if(bad||overlap)return alert('⚠️ เวลาการทำงานซ้อนกันหรือรูปแบบเวลาไม่ถูกต้อง');publish(`smartfarm/schedule/${selectedRelay}/set`,JSON.stringify({slots})).catch(e=>alert(e.message))})}
window.addEventListener('hashchange',()=>{route=location.hash.slice(1)||'dashboard';render()});document.querySelector('#alertsBtn').onclick=()=>document.querySelector('#view').scrollIntoView({behavior:'smooth'});subscribe(render);connect();render();setInterval(connect,15000);
